// Generates Vercel serverless functions (api/_lib/*) from the Supabase Edge
// Functions in supabase/functions, using the same conversion as server/index.ts.
// Run with: npm run gen:api   (the output is committed, so Vercel needs no extra step)
import fs from "node:fs";
import path from "node:path";

const root = path.resolve(path.dirname(new URL(import.meta.url).pathname), "..");
const srcDir = path.join(root, "supabase", "functions");
const outRoot = path.join(root, "api", "_lib");

const header = `// @ts-nocheck
// GENERATED by scripts/gen-api.mjs from supabase/functions. Do not edit; edit the source and rerun.
const Deno = { env: { get: (k: string) => (k === "LOVABLE_API_KEY" ? process.env.GEMINI_API_KEY || undefined : process.env[k]) } };
`;

function convert(code, isIndex) {
  const body = code
    .split("\n")
    .filter((l) => !/^import .*https:\/\/deno\.land/.test(l))
    .join("\n")
    .replace(/^serve\(/m, "export default (")
    .replaceAll("https://ai.gateway.lovable.dev/v1/chat/completions", "https://generativelanguage.googleapis.com/v1beta/openai/chat/completions")
    .replaceAll("'google/gemini-2.5-flash'", '(process.env.GEMINI_MODEL || "gemini-3.8-flash")');
  return (isIndex ? header : "// @ts-nocheck\n// GENERATED by scripts/gen-api.mjs. Do not edit.\n") + body;
}

fs.rmSync(outRoot, { recursive: true, force: true });
for (const name of fs.readdirSync(srcDir)) {
  const dir = path.join(srcDir, name);
  if (!fs.statSync(dir).isDirectory()) continue;
  const outDir = path.join(outRoot, name);
  fs.mkdirSync(outDir, { recursive: true });
  for (const f of fs.readdirSync(dir).filter((f) => f.endsWith(".ts"))) {
    const src = fs.readFileSync(path.join(dir, f), "utf8").replace(/from '\.\/([\w-]+)\.ts'/g, "from './$1.js'");
    fs.writeFileSync(path.join(outDir, f), convert(src, f === "index.ts"));
  }
  console.log("generated api/_lib/" + name);
}
